1	/**
2	 * Stable, serializable error vocabulary shared by application boundaries.
3	 *
4	 * Keep these values independent of framework or provider error classes so
5	 * clients can safely persist and render them across version boundaries.
6	 */
7	export const APP_ERROR_CODES = [
8	  "VALIDATION_FAILED",
9	  "AUTHENTICATION_REQUIRED",
10	  "AUTHENTICATION_FAILED",
11	  "PERMISSION_DENIED",
12	  "NOT_FOUND",
13	  "CONFLICT",
14	  "RATE_LIMITED",
15	  "TIMEOUT",
16	  "NETWORK_UNAVAILABLE",
17	  "CONFIGURATION_ERROR",
18	  "PROVIDER_ERROR",
19	  "MALFORMED_RESPONSE",
20	  "INTERNAL_ERROR",
21	] as const;
22	
23	export type AppErrorCode = (typeof APP_ERROR_CODES)[number];
24	
25	export type AppErrorSource =
26	  | "application"
27	  | "validation"
28	  | "convex"
29	  | "auth"
30	  | "fetch"
31	  | "provider"
32	  | "unknown";
33	
34	export type AppErrorRecoveryAction =
35	  | "fix-input"
36	  | "sign-in"
37	  | "retry"
38	  | "retry-later"
39	  | "check-connection"
40	  | "check-configuration"
41	  | "choose-provider"
42	  | "contact-support"
43	  | "none";
44	
45	export interface AppErrorRecovery {
46	  action: AppErrorRecoveryAction;
47	  canRetry: boolean;
48	  retryAfterMs?: number;
49	}
50	
51	export type SafeErrorMetadataValue =
52	  | string
53	  | number
54	  | boolean
55	  | null
56	  | SafeErrorMetadataValue[]
57	  | { [key: string]: SafeErrorMetadataValue };
58	
59	export interface AppError {
60	  code: AppErrorCode;
61	  message: string;
62	  referenceId: string;
63	  source: AppErrorSource;
64	  recovery: AppErrorRecovery;
65	  status?: number;
66	  metadata?: Record<string, SafeErrorMetadataValue>;
67	}
68	
69	export type ApplicationResult<T> =
70	  | { ok: true; value: T }
71	  | { ok: false; error: AppError };
72	
73	export interface AppErrorOptions {
74	  source?: AppErrorSource;
75	  referenceId?: string;
76	  status?: number;
77	  recovery?: Partial<AppErrorRecovery>;
78	  metadata?: Record<string, unknown>;
79	  validationKey?: string;
80	}
