124	const SENSITIVE_KEY_PATTERN =
125	  /(?:^|[_-])(?:api[_-]?key|access[_-]?token|refresh[_-]?token|id[_-]?token|auth(?:orization)?|bearer|credential|secret|password|passcode|cookie|session|jwt|private[_-]?key|client[_-]?secret|prompt|system[_-]?prompt|transcript|conversation|draft|manuscript|document|content|messages?|completion|input|output|request[_-]?(?:body|payload)|response[_-]?(?:body|payload)|provider[_-]?(?:body|response)|body|stack|stacktrace|cause|url|uri|endpoint|base[_-]?url|host|origin|webhook)(?:$|[_-])/i;
126	
127	const SAFE_METADATA_KEY_PATTERN =
128	  /^(?:field|fields|feature|operation|method|provider|providerId|providerType|model|attempt|statusText|kind|type|resource|limit|retryAfterMs)$/i;
