130	const SECRET_VALUE_PATTERNS: RegExp[] = [
131	  /\b(?:bearer|basic)\s+[^\s,;]+/gi,
132	  /\b(?:sk|pk|rk|sess|pat|ghp|github_pat|xox[baprs]|AIza)[-_A-Za-z0-9]{12,}\b/g,
133	  /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}(?:\.[A-Za-z0-9_-]{8,})?\b/g,
134	  /\b(?:api[_-]?key|access[_-]?token|refresh[_-]?token|secret|password|authorization)\s*[:=]\s*["']?[^\s,"';}]+/gi,
135	  /\bhttps?:\/\/[^\s"'<>]+/gi,
136	  /\b(?:wss?|ftp):\/\/[^\s"'<>]+/gi,
137	];
