139	const NETWORK_ERROR_PATTERNS = [
140	  /failed to fetch/i,
141	  /fetch failed/i,
142	  /network(?: request)? failed/i,
143	  /networkerror/i,
144	  /load failed/i,
145	  /connection (?:refused|reset|closed)/i,
146	  /\bECONN(?:REFUSED|RESET|ABORTED)\b/i,
147	  /\bENOTFOUND\b/i,
