171	const CONFIG_PATTERNS = [
172	  /not configured/i,
173	  /configuration/i,
174	  /missing (?:api )?key/i,
175	  /api key is missing/i,
176	  /environment variable/i,
177	  /base url.*required/i,
178	  /deployment address/i,
179	  /no provider/i,
180	];
