182	const VALIDATION_KEY_PATTERNS: Array<[RegExp, string]> = [
183	  [
184	    /\bemail\b.*\b(required|missing)\b|\b(required|missing)\b.*\bemail\b/i,
185	    "email_required",
186	  ],
187	  [/\bemail\b.*\b(invalid|valid email|format)\b/i, "email_invalid"],
188	  [/\bpassword\b.*\b(required|missing)\b/i, "password_required"],
189	  [/\bpassword\b.*\b(short|characters?|length)\b/i, "password_too_short"],
190	  [/\bhandle\b.*\b(required|missing)\b/i, "handle_required"],
191	  [/\bhandle\b.*\b(invalid|letters|numbers|format)\b/i, "handle_invalid"],
192	  [/\bfile\b.*\btoo large\b|\bpayload too large\b/i, "file_too_large"],
193	  [
194	    /\b(file|media)\b.*\b(type|format).*\b(unsupported|invalid)\b/i,
195	    "unsupported_file_type",
196	  ],
197	  [/\b(required|missing|required field)\b/i, "required"],
198	  [/\btoo short\b|\bminimum length\b/i, "too_short"],
199	  [/\btoo long\b|\bmaximum length\b/i, "too_long"],
200	  [/\bformat\b/i, "invalid_format"],
201	];
