203	function defaultRecovery(code: AppErrorCode): AppErrorRecovery {
204	  switch (code) {
205	    case "VALIDATION_FAILED":
206	      return { action: "fix-input", canRetry: true };
207	    case "AUTHENTICATION_REQUIRED":
208	    case "AUTHENTICATION_FAILED":
209	      return { action: "sign-in", canRetry: true };
210	    case "RATE_LIMITED":
211	      return { action: "retry-later", canRetry: true };
212	    case "TIMEOUT":
213	    case "PROVIDER_ERROR":
214	    case "MALFORMED_RESPONSE":
215	    case "INTERNAL_ERROR":
216	      return { action: "retry", canRetry: true };
217	    case "NETWORK_UNAVAILABLE":
218	      return { action: "check-connection", canRetry: true };
219	    case "CONFIGURATION_ERROR":
220	      return { action: "check-configuration", canRetry: false };
221	    case "PERMISSION_DENIED":
222	    case "NOT_FOUND":
223	    case "CONFLICT":
224	      return { action: "none", canRetry: false };
225	  }
226	}
227	
228	function referenceId(): string {
229	  try {
230	    if (typeof crypto !== "undefined" && crypto.randomUUID) {
231	      return `err_${crypto.randomUUID()}`;
232	    }
233	  } catch {
234	    // Fall through to a runtime-independent identifier.
235	  }
236	  return `err_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 14)}`;
237	}
238	
239	function safeReferenceId(candidate: unknown): string {
240	  return typeof candidate === "string" &&
241	    /^[A-Za-z0-9][A-Za-z0-9._:-]{5,127}$/.test(candidate)
242	    ? candidate
243	    : referenceId();
244	}
245	
246	function normalizeStatus(value: unknown): number | undefined {
247	  if (typeof value !== "number" || !Number.isInteger(value)) return undefined;
248	  return value >= 100 && value <= 599 ? value : undefined;
249	}
250	
251	function normalizeRetryAfterMs(value: unknown): number | undefined {
252	  if (typeof value === "string" && value.trim() !== "") {
253	    const seconds = Number(value);
254	    value = Number.isFinite(seconds) ? seconds * 1000 : undefined;
255	  }
256	  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
257	    return undefined;
258	  }
259	  return Math.min(Math.round(value), 24 * 60 * 60 * 1000);
260	}
261	
262	function toRecord(value: unknown): Record<string, unknown> | undefined {
263	  return value !== null && typeof value === "object"
264	    ? (value as Record<string, unknown>)
265	    : undefined;
266	}
267	
268	function stringProperty(
269	  record: Record<string, unknown> | undefined,
270	  ...keys: string[]
271	): string | undefined {
272	  for (const key of keys) {
273	    const value = record?.[key];
274	    if (typeof value === "string" && value.trim()) return value.trim();
275	  }
276	  return undefined;
277	}
278	
279	function numberProperty(
280	  record: Record<string, unknown> | undefined,
281	  ...keys: string[]
282	): number | undefined {
283	  for (const key of keys) {
284	    const value = record?.[key];
285	    if (typeof value === "number" && Number.isFinite(value)) return value;
286	  }
287	  return undefined;
288	}
289	
290	function booleanProperty(
291	  record: Record<string, unknown> | undefined,
292	  ...keys: string[]
293	): boolean | undefined {
294	  for (const key of keys) {
295	    const value = record?.[key];
296	    if (typeof value === "boolean") return value;
297	  }
298	  return undefined;
299	}
300	
301	function normalizedTag(value: unknown): string | undefined {
302	  if (typeof value !== "string") return undefined;
303	  const normalized = value
304	    .trim()
305	    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
306	    .replace(/[^A-Za-z0-9]+/g, "_")
307	    .replace(/^_+|_+$/g, "")
308	    .toUpperCase();
309	  return normalized || undefined;
310	}
311	
312	function codeFromTag(value: unknown): AppErrorCode | undefined {
313	  const tag = normalizedTag(value);
314	  if (!tag) return undefined;
315	  if (APP_ERROR_CODE_SET.has(tag)) return tag as AppErrorCode;
316	  return CODE_ALIASES[tag];
317	}
318	
319	function statusToCode(status: number, source: AppErrorSource): AppErrorCode {
320	  if (status === 400 || status === 413 || status === 415 || status === 422) {
321	    return "VALIDATION_FAILED";
322	  }
323	  if (status === 401) {
324	    return source === "auth"
325	      ? "AUTHENTICATION_FAILED"
326	      : "AUTHENTICATION_REQUIRED";
327	  }
328	  if (status === 403) return "PERMISSION_DENIED";
329	  if (status === 404) return "NOT_FOUND";
330	  if (status === 408 || status === 504) return "TIMEOUT";
331	  if (status === 409) return "CONFLICT";
332	  if (status === 429) return "RATE_LIMITED";
333	  if (status === 502 || status === 503) {
334	    return source === "provider" ? "PROVIDER_ERROR" : "NETWORK_UNAVAILABLE";
335	  }
336	  if (status >= 500) {
337	    return source === "provider" ? "PROVIDER_ERROR" : "INTERNAL_ERROR";
338	  }
339	  return source === "provider" ? "PROVIDER_ERROR" : "INTERNAL_ERROR";
340	}
341	
342	function validationMessage(key: unknown, rawHint?: string): string {
343	  const normalizedKey = normalizedTag(key)?.toLowerCase();
344	  if (normalizedKey && VALIDATION_MESSAGES[normalizedKey]) {
345	    return VALIDATION_MESSAGES[normalizedKey];
346	  }
347	  if (rawHint) {
348	    for (const [pattern, mappedKey] of VALIDATION_KEY_PATTERNS) {
349	      if (pattern.test(rawHint)) return VALIDATION_MESSAGES[mappedKey];
350	    }
351	  }
352	  return DEFAULT_MESSAGES.VALIDATION_FAILED;
353	}
354	
355	function redactedString(value: string): string {
356	  if (!value) return value;
357	  let redacted = value.replace(/\r?\n[\s\S]*/g, " [REDACTED]");
358	  for (const pattern of SECRET_VALUE_PATTERNS) {
359	    redacted = redacted.replace(pattern, "[REDACTED]");
360	  }
361	  if (redacted.length > MAX_SAFE_STRING_LENGTH) {
362	    redacted = `${redacted.slice(0, MAX_SAFE_STRING_LENGTH)}…`;
363	  }
364	  return redacted;
365	}
366	
367	function sanitizeMetadataValue(
368	  value: unknown,
369	  key: string,
370	  depth: number,
371	  seen: WeakSet<object>,
372	): SafeErrorMetadataValue | undefined {
373	  if (SENSITIVE_KEY_PATTERN.test(key)) return "[REDACTED]";
374	  if (depth > 0 && !SAFE_METADATA_KEY_PATTERN.test(key)) return "[REDACTED]";
375	  if (value === null) return null;
376	  if (typeof value === "boolean") return value;
377	  if (typeof value === "number") {
378	    return Number.isFinite(value) ? value : undefined;
379	  }
380	  if (typeof value === "string") return redactedString(value);
381	  if (typeof value === "bigint") return value.toString();
382	  if (
383	    typeof value === "undefined" ||
384	    typeof value === "function" ||
385	    typeof value === "symbol"
386	  ) {
387	    return undefined;
388	  }
389	  if (depth >= MAX_METADATA_DEPTH) return "[REDACTED]";
390	  if (seen.has(value)) return "[REDACTED]";
391	  seen.add(value);
392	  if (Array.isArray(value)) {
393	    return value
394	      .slice(0, MAX_ARRAY_ITEMS)
395	      .map((item) => sanitizeMetadataValue(item, key, depth + 1, seen))
396	      .filter((item): item is SafeErrorMetadataValue => item !== undefined);
397	  }
398	  const output: Record<string, SafeErrorMetadataValue> = {};
399	  for (const [childKey, childValue] of Object.entries(value).slice(
400	    0,
401	    MAX_METADATA_KEYS,
402	  )) {
403	    const sanitized = sanitizeMetadataValue(
404	      childValue,
405	      childKey,
406	      depth + 1,
407	      seen,
408	    );
409	    if (sanitized !== undefined) output[childKey] = sanitized;
410	  }
411	  return output;
412	}
413	
414	/**
415	 * Sanitizes optional diagnostic metadata. Callers should still prefer small,
416	 * allowlisted context; this function is the final guard before serialization.
417	 */
418	export function sanitizeErrorMetadata(
419	  metadata: Record<string, unknown> | undefined,
420	): Record<string, SafeErrorMetadataValue> | undefined {
421	  if (!metadata) return undefined;
422	  const sanitized = sanitizeMetadataValue(
423	    metadata,
424	    "metadata",
425	    0,
426	    new WeakSet(),
427	  );
428	  if (!sanitized || Array.isArray(sanitized) || typeof sanitized !== "object") {
429	    return undefined;
430	  }
431	  return Object.keys(sanitized).length ? sanitized : undefined;
432	}
433	
434	function pickSafeMetadata(
435	  record: Record<string, unknown> | undefined,
436	): Record<string, unknown> | undefined {
437	  if (!record) return undefined;
438	  const metadata: Record<string, unknown> = {};
439	  for (const [key, value] of Object.entries(record)) {
440	    if (SAFE_METADATA_KEY_PATTERN.test(key)) metadata[key] = value;
441	  }
442	  return Object.keys(metadata).length ? metadata : undefined;
443	}
444	
445	export function createAppError(
446	  code: AppErrorCode,
447	  options: AppErrorOptions = {},
448	): AppError {
449	  const status = normalizeStatus(options.status);
450	  const baseRecovery = defaultRecovery(code);
451	  const retryAfterMs = normalizeRetryAfterMs(options.recovery?.retryAfterMs);
452	  const recovery: AppErrorRecovery = {
453	    action: options.recovery?.action ?? baseRecovery.action,
454	    canRetry: options.recovery?.canRetry ?? baseRecovery.canRetry,
455	    ...(retryAfterMs === undefined ? {} : { retryAfterMs }),
456	  };
457	  const metadata = sanitizeErrorMetadata(options.metadata);
458	  return {
459	    code,
460	    message:
461	      code === "VALIDATION_FAILED"
462	        ? validationMessage(options.validationKey)
463	        : DEFAULT_MESSAGES[code],
464	    referenceId: safeReferenceId(options.referenceId),
465	    source: options.source ?? "application",
466	    recovery,
467	    ...(status === undefined ? {} : { status }),
468	    ...(metadata ? { metadata } : {}),
469	  };
470	}
471	
472	export function successResult<T>(value: T): ApplicationResult<T> {
473	  return { ok: true, value };
474	}
475	
476	export function failureResult<T = never>(
477	  error: unknown,
478	  options?: AppErrorOptions,
479	): ApplicationResult<T> {
480	  return { ok: false, error: normalizeApplicationError(error, options) };
481	}
482	
483	export function isAppError(value: unknown): value is AppError {
484	  const record = toRecord(value);
485	  const recovery = toRecord(record?.recovery);
486	  return Boolean(
487	    record &&
488	      APP_ERROR_CODE_SET.has(String(record.code)) &&
489	      typeof record.message === "string" &&
490	      typeof record.referenceId === "string" &&
491	      APP_ERROR_SOURCE_SET.has(record.source as AppErrorSource) &&
492	      recovery &&
493	      RECOVERY_ACTION_SET.has(recovery.action as AppErrorRecovery["action"]) &&
494	      typeof recovery.canRetry === "boolean",
495	  );
496	}
497	
498	function rebuildAppError(error: AppError, options: AppErrorOptions): AppError {
499	  return createAppError(error.code, {
500	    source: options.source ?? error.source,
501	    referenceId: options.referenceId ?? error.referenceId,
502	    status: options.status ?? error.status,
503	    recovery: { ...error.recovery, ...options.recovery },
504	    metadata: { ...error.metadata, ...options.metadata },
505	    validationKey: options.validationKey,
506	  });
507	}
508	
509	function isResponse(value: unknown): value is Response {
510	  return typeof Response !== "undefined" && value instanceof Response;
511	}
512	
